1	"use client";
2	
3	import { Layers } from "lucide-react";
4	import { useCallback, useMemo, useState } from "react";
5	import { useBoardTrackingContext } from "../KanbanBoard/KanbanBoard.context";
6	import { groupTrackedTasks } from "./groupTasks";
7	import type { TrackedStatus } from "./TaskTrackingPanel.types";
8	import { TaskTrackingSection } from "./TaskTrackingSection";
9	import type { ParsedFeature, ParsedTask } from "@/services/yaml-parser";
10	
11	const ALL_EXPANDED: Record<TrackedStatus, boolean> = {
12	  blocked: true,
13	  in_progress: true,
14	  reviewing: true,
15	  in_review: true,
16	  ready: true,
17	};
18	
19	export function TaskTrackingPanel() {
20	  const {
21	    trackedFeatures,
22	    openTaskTab,
23	    openTaskTabNewSession,
24	  } = useBoardTrackingContext();
25	
26	  const sections = useMemo(
27	    () => groupTrackedTasks(trackedFeatures),
28	    [trackedFeatures],
29	  );
30	
31	  const [expanded, setExpanded] =
32	    useState<Record<TrackedStatus, boolean>>(ALL_EXPANDED);
33	
34	  const toggleSection = useCallback((status: TrackedStatus) => {
35	    setExpanded((prev) => ({ ...prev, [status]: !prev[status] }));
36	  }, []);
37	
38	  const handleSelectTask = useCallback(
39	    (task: ParsedTask, _feature: ParsedFeature) => {
40	      openTaskTab(task);
41	    },
42	    [openTaskTab],
43	  );
44	
45	  const handleOpenTaskTab = useCallback(
46	    (task: ParsedTask) => {
47	      openTaskTab(task);
48	    },
49	    [openTaskTab],
50	  );
51	
52	  const handleOpenTaskTabNewSession = useCallback(
53	    (task: ParsedTask) => {
54	      openTaskTabNewSession(task);
55	    },
56	    [openTaskTabNewSession],
57	  );
58	
59	  return (
60	    <aside
61	      className="flex shrink-0 flex-col overflow-hidden border-r border-border bg-surface-secondary"
62	      style={{ width: "20.25rem", maxWidth: "100vw" }}
63	      aria-label="Tasks sidebar"
64	    >
65	      <header className="shrink-0 border-b border-border px-4 py-3">
66	        <div className="flex items-center gap-2">
67	          <Layers
68	            className="h-4 w-4 shrink-0 text-success"
69	            aria-hidden="true"
70	          />
71	          <h2 className="text-[11px] font-bold uppercase tracking-[0.18em] text-text-primary">
72	            Tasks Sidebar
73	          </h2>
74	        </div>
75	      </header>
76	
77	      <div className="flex-1 overflow-y-auto">
78	        {sections.map((section) => (
79	          <TaskTrackingSection
80	            key={section.status}
81	            section={section}
82	            isExpanded={expanded[section.status]}
83	            onToggle={() => toggleSection(section.status)}
84	            onSelectTask={handleSelectTask}
85	            onOpenTaskTab={handleOpenTaskTab}
86	            onOpenTaskTabNewSession={handleOpenTaskTabNewSession}
