1	/**
2	 * T6 Browser QA — In-browser verification of regression cases.
3	 *
4	 * Subtask 8: Verify the status, repository, Task Docs, pagination, and
5	 * feature-card regression cases in-browser using Playwright.
6	 *
7	 * Navigates to /test/board-qa which renders all key components in
8	 * isolation with mock data. Verifies DOM structure and captures
9	 * screenshots as browser QA evidence.
10	 *
11	 * Run:  npx playwright test --config=playwright.config.ts
12	 */
13	
14	import { test, expect, Page } from "@playwright/test";
15	
16	// ═══════════════════════════════════════════════════════════════════════
17	// Helpers
18	// ═══════════════════════════════════════════════════════════════════════
19	
20	async function navigateToQAPage(page: Page) {
21	  await page.goto("/test/board-qa");
22	  // Wait for the page heading to confirm full render (avoid networkidle
23	  // which can time out at 60 s on dev servers with long-lived connections)
24	  await page.waitForSelector("h1", { timeout: 10000 });
25	}
26	
27	// ═══════════════════════════════════════════════════════════════════════
28	// Test: Feature Card Regression
29	// ═══════════════════════════════════════════════════════════════════════
30	
31	test.describe("T6 Browser QA — Feature Card Regression", () => {
32	  test("feature cards render ID smaller than title and prioritize title width", async ({
33	    page,
34	  }) => {
35	    await navigateToQAPage(page);
36	
37	    // Scroll to feature cards section
38	    await page.locator("#section-feature-cards").scrollIntoViewIfNeeded();
39	    await page.waitForTimeout(500);
40	
41	    // Take screenshot of the section
42	    await page.locator("#section-feature-cards").screenshot({
43	      path: "screenshots/t6-feature-cards.png",
44	    });
45	
46	    // Verify all cards have the expected DOM structure
47	    const cards = page.locator(
48	      "#section-feature-cards [data-feature-card-status]",
49	    );
50	    const count = await cards.count();
51	    expect(count).toBeGreaterThanOrEqual(3);
52	
53	    // First card (Normal — ID + Title): should have both line-clamp-2 title and uppercase ID
54	    const firstCard = cards.nth(0);
55	    await expect(firstCard.locator(".line-clamp-2")).toBeVisible();
56	
57	    // The ID element should use text-[11px] and uppercase
58	    const idEl = firstCard.locator(".text-\\[11px\\].uppercase");
59	    await expect(idEl).toBeVisible();
60	    const idText = await idEl.textContent();
61	    expect(idText).toBe("kanban-board-feature");
62	
63	    // Title appears in DOM before ID (title uses line-clamp-2, above the ID line)
64	    const firstCardHtml = await firstCard.innerHTML();
65	    const titlePos = firstCardHtml.indexOf("Feature Kanban Board");
66	    const idPos = firstCardHtml.indexOf("kanban-board-feature");
67	    // Title should appear before the ID metadata line in the DOM
68	    // (the title element is the first p.line-clamp-2, ID is a later p.truncate)
69	    expect(titlePos).toBeLessThan(idPos);
70	
71	    // Long ID card: should truncate
72	    const longIdCard = cards.nth(1);
73	    const longIdEl = longIdCard.locator(".truncate");
74	    await expect(longIdEl).toBeVisible();
75	
76	    // Long title card: should use line-clamp-2 (wrapping)
77	    const longTitleCard = cards.nth(2);
78	    await expect(longTitleCard.locator(".line-clamp-2")).toBeVisible();
79	
80	    // Same ID/title card: ID line should be hidden
81	    const sameCard = cards.nth(3);
82	    // Check that the ID doesn't appear twice in text content
83	    const sameCardText = await sameCard.textContent();
84	    // "simple-feature" should appear only once (just the title)
85	    const occurrences = (sameCardText?.match(/simple-feature/g) || []).length;
86	    // In HTML, the title appears in: the <p> text, the aria-label, and the title attribute
87	    // But the ID metadata line (separate <p>) should NOT be present
88	    const idMetadataLines = await sameCard
89	      .locator(".truncate.text-\\[11px\\].uppercase")
90	      .count();
91	    expect(idMetadataLines).toBe(0);
92	
93	    // Verify aria-label confirms tab-opening behavior
94	    const ariaLabel = await firstCard.getAttribute("aria-label");
95	    expect(ariaLabel).toContain("Open feature tab for");
96	  });
97	
98	  test("feature cards suppress status tag in Feature mode", async ({
99	    page,
100	  }) => {
101	    await navigateToQAPage(page);
102	
103	    // Scroll to no-status-pill section
104	    await page.locator("#section-no-status-pill").scrollIntoViewIfNeeded();
105	    await page.waitForTimeout(500);
106	
107	    await page.locator("#section-no-status-pill").screenshot({
108	      path: "screenshots/t6-no-status-pill.png",
109	    });
110	
111	    // All 8 feature cards should NOT contain status labels
112	    const statusLabels = [
113	      "In Design",
114	      "In TDD",
115	      "Ready",
116	      "In Progress",
117	      "Handoff",
118	      "Done",
119	      "Blocked",
120	      "Cancelled",
