125	export function BoardProvider({
126	  workspaceDetail,
127	  children,
128	}: BoardProviderProps) {
129	  const { features, loading, error, reload } = useBoardData(
130	    workspaceDetail.id,
131	    {
132	      initialData: workspaceDetail,
133	    },
134	  );
135	  const { trackedFeatures, reload: reloadTracking } = usePullRequestTaskData(
136	    workspaceDetail.id,
137	  );
138	
139	  const {
140	    syncCurrentWorkspace,
141	    syncingWorkspace: syncing,
142	    syncError: wsyncError,
143	    openTaskTab: wsOpenTaskTab,
144	    openFeatureTab: wsOpenFeatureTab,
145	  } = useWorkspaceActionsContext();
146	
147	  const [boardMode, setBoardModeState] = useState<BoardMode>(
148	    () => getStoredBoardMode() ?? getDefaultBoardMode(),
149	  );
150	  const [taskSearchQuery, setTaskSearchQuery] = useState("");
151	  const [featureSearchQuery, setFeatureSearchQuery] = useState("");
152	  const [taskActiveFilters, setTaskActiveFiltersState] =
153	    useState<ActiveFilters>(() => ({
154	      statuses: getStoredStatusFilter() ?? getDefaultStatusFilter(),
155	    }));
156	  const [featureActiveFilters, setFeatureActiveFiltersState] =
157	    useState<FeatureActiveFilters>(() => ({
158	      statuses:
159	        getStoredFeatureStatusFilter() ?? getDefaultFeatureStatusFilter(),
160	    }));
161	  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
162	    () => new Set(),
163	  );
164	  const [taskPage, setTaskPage] = useState(1);
165	  const [featurePage, setFeaturePage] = useState(1);
166	  const [taskLimit, setTaskLimit] = useState(BOARD_DEFAULT_LIMIT);
167	  const [featureLimit, setFeatureLimit] = useState(BOARD_DEFAULT_LIMIT);
168	
169	  // Build a map of feature backend ID -> feature lifecycle status from the
170	  // already-loaded features array.  Passed to useBackendTaskSearch so
171	  // adaptTaskSummariesToFeatures can set the correct feature lifecycle status
172	  // on each ParsedFeature instead of falling back to a task-derived value.
173	  const featureStatusMap = useMemo(() => {
174	    const map = new Map<string, string>();
175	    for (const f of features) {
176	      if (f.backendId && f.featureStatus) {
177	        map.set(f.backendId, f.featureStatus);
178	      }
179	    }
180	    return map as ReadonlyMap<string, string>;
181	  }, [features]);
182	
183	  // Backend search hooks
184	  const deferredTaskSearchQuery = useDeferredValue(taskSearchQuery);
185	  const deferredFeatureSearchQuery = useDeferredValue(featureSearchQuery);
186	  const trimmedTaskQuery = deferredTaskSearchQuery.trim();
187	
188	  // Backend search is active when either search text is present OR the status
189	  // filter is a non-default subset (not all statuses selected).  When every
190	  // status is selected there is no effective filter, so we fall back to the
191	  // workspace root payload.
192	  const taskStatusFilterActive =
193	    taskActiveFilters.statuses.length > 0 &&
194	    !isAllStatusFilterSelected(taskActiveFilters.statuses);
195	  const taskSearchActive =
196	    boardMode === "task" &&
197	    (trimmedTaskQuery.length > 0 || taskStatusFilterActive);
198	
199	  // Reset page to 1 when search query, filters, or limit change
200	  const prevTaskQueryRef = useRef(trimmedTaskQuery);
201	  const prevTaskStatusRef = useRef(
202	    taskActiveFilters.statuses.join(","),
203	  );
204	  const prevTaskLimitRef = useRef(taskLimit);
205	  useEffect(() => {
206	    const currentStatus = taskActiveFilters.statuses.join(",");
207	    if (
208	      trimmedTaskQuery !== prevTaskQueryRef.current ||
209	      currentStatus !== prevTaskStatusRef.current ||
210	      taskLimit !== prevTaskLimitRef.current
211	    ) {
212	      setTaskPage(1);
213	    }
214	    prevTaskQueryRef.current = trimmedTaskQuery;
215	    prevTaskStatusRef.current = currentStatus;
216	    prevTaskLimitRef.current = taskLimit;
217	  }, [trimmedTaskQuery, taskActiveFilters.statuses, taskLimit]);
218	
219	  const taskSearchParams = useMemo(() => {
220	    if (!taskSearchActive) return {};
221	
222	    const status = taskStatusFilterActive
223	      ? taskActiveFilters.statuses.join(",")
224	      : undefined;
225	
226	    return {
227	      title: trimmedTaskQuery || undefined,
228	      status,
229	      page: taskPage,
230	      limit: taskLimit,
231	      sort: BOARD_DEFAULT_SORT,
232	    };
233	  }, [trimmedTaskQuery, taskActiveFilters.statuses, taskPage, taskSearchActive, taskStatusFilterActive, taskLimit]);
234	
235	  const {
236	    results: backendTaskResults,
237	    searching: taskSearching,
238	    searchError: taskSearchError,
239	    pagination: taskPagination,
240	  } = useBackendTaskSearch(workspaceDetail.id, taskSearchParams, featureStatusMap);
241	
242	  const trimmedFeatureQuery = deferredFeatureSearchQuery.trim();
243	
244	  // Feature-mode backend search activates when search text is present OR the
245	  // status filter is a non-default subset.  All-feature-statuses-selected
246	  // means no effective filter — fall back to the workspace root payload.
247	  const featureStatusFilterActive =
248	    featureActiveFilters.statuses.length > 0 &&
249	    !isAllFeatureStatusFilterSelected(featureActiveFilters.statuses);
250	  const featureSearchActive =
251	    boardMode === "feature" &&
252	    (trimmedFeatureQuery.length > 0 || featureStatusFilterActive);
253	
254	  const prevFeatureQueryRef = useRef(trimmedFeatureQuery);
255	  const prevFeatureStatusRef = useRef(
256	    featureActiveFilters.statuses.join(","),
257	  );
258	  const prevFeatureLimitRef = useRef(featureLimit);
259	  useEffect(() => {
260	    const currentStatus = featureActiveFilters.statuses.join(",");
261	    if (
262	      trimmedFeatureQuery !== prevFeatureQueryRef.current ||
263	      currentStatus !== prevFeatureStatusRef.current ||
264	      featureLimit !== prevFeatureLimitRef.current
265	    ) {
266	      setFeaturePage(1);
267	    }
268	    prevFeatureQueryRef.current = trimmedFeatureQuery;
269	    prevFeatureStatusRef.current = currentStatus;
270	    prevFeatureLimitRef.current = featureLimit;
271	  }, [trimmedFeatureQuery, featureActiveFilters.statuses, featureLimit]);
272	
273	  const featureSearchParams = useMemo(() => {
274	    if (!featureSearchActive) return {};
275	
276	    const status = featureStatusFilterActive
277	      ? featureActiveFilters.statuses.join(",")
278	      : undefined;
279	
280	    return {
281	      title: trimmedFeatureQuery || undefined,
282	      status,
283	      page: featurePage,
284	      limit: featureLimit,
285	      sort: BOARD_DEFAULT_SORT,
286	    };
287	  }, [trimmedFeatureQuery, featureActiveFilters.statuses, featurePage, featureSearchActive, featureStatusFilterActive, featureLimit]);
288	
289	  const {
290	    results: backendFeatureResults,
291	    searching: featureSearching,
292	    searchError: featureSearchError,
293	    pagination: featurePagination,
294	  } = useBackendFeatureSearch(workspaceDetail.id, featureSearchParams);
295	
296	  const toggleFeature = useCallback((featureId: string) => {
297	    setExpandedFeatureIds((prev) => {
298	      const next = new Set(prev);
299	      if (next.has(featureId)) {
300	        next.delete(featureId);
301	      } else {
302	        next.add(featureId);
303	      }
304	      return next;
305	    });
306	  }, []);
307	
308	  const reloadAll = useCallback(() => {
309	    reload();
310	    reloadTracking();
311	  }, [reload, reloadTracking]);
312	
313	  const reloadAllRef = useRef(reloadAll);
314	  useEffect(() => {
315	    reloadAllRef.current = reloadAll;
316	  }, [reloadAll]);
317	
318	  useEffect(() => {
319	    const id = setInterval(() => {
320	      reloadAllRef.current();
321	    }, 60_000);
322	    return () => clearInterval(id);
323	  }, []);
324	
325	  const handleSetBoardMode = useCallback((mode: BoardMode) => {
326	    saveBoardMode(mode);
327	    setBoardModeState(mode);
328	  }, []);
329	
330	  const handleSetTaskActiveFilters = useCallback((filters: ActiveFilters) => {
331	    saveStatusFilter(filters.statuses);
332	    setTaskActiveFiltersState(filters);
333	  }, []);
334	
335	  const handleSetFeatureActiveFilters = useCallback(
336	    (filters: FeatureActiveFilters) => {
337	      saveFeatureStatusFilter(filters.statuses);
338	      setFeatureActiveFiltersState(filters);
339	    },
340	    [],
341	  );
342	
343	  const syncBoard = useCallback(() => {
344	    syncCurrentWorkspace().catch(() => {
345	      // error captured in syncError
346	    });
347	  }, [syncCurrentWorkspace]);
348	
349	  const openTaskTab = useCallback(
350	    (task: ParsedTask) => {
351	      if (!task.backendId) return;
352	      wsOpenTaskTab({
353	        taskId: task.backendId,
354	        taskName: task.id,
355	        title: task.title,
356	        featureId: task.featureBackendId,
357	      });
358	    },
359	    [wsOpenTaskTab],
360	  );
361	
362	  const openTaskTabNewSession = useCallback(
363	    (task: ParsedTask) => {
364	      if (!task.backendId) return;
365	      wsOpenTaskTab(
366	        {
367	          taskId: task.backendId,
368	          taskName: task.id,
369	          title: task.title,
370	          featureId: task.featureBackendId,
371	        },
372	        { forceNewSession: true },
373	      );
374	    },
375	    [wsOpenTaskTab],
376	  );
377	
378	  const openFeatureTab = useCallback(
379	    (feature: ParsedFeature) => {
380	      if (!feature.backendId) return;
381	      wsOpenFeatureTab({
382	        featureId: feature.backendId,
383	        featureName: feature.id,
384	        title: feature.title || feature.id,
385	      });
386	    },
387	    [wsOpenFeatureTab],
388	  );
389	
390	  const openFeatureTabNewSession = useCallback(
391	    (feature: ParsedFeature) => {
392	      if (!feature.backendId) return;
393	      wsOpenFeatureTab(
394	        {
395	          featureId: feature.backendId,
396	          featureName: feature.id,
397	          title: feature.title || feature.id,
398	        },
399	        { forceNewSession: true },
400	      );
401	    },
402	    [wsOpenFeatureTab],
403	  );
404	
405	  // Map workspace sync error to BoardLoadError shape
406	  const syncError = useMemo<BoardLoadError | null>(
407	    () =>
408	      wsyncError
409	        ? {
410	            kind: "network_error",
411	            message: wsyncError.message ?? "Sync failed",
412	            retryable: wsyncError.retryable,
413	          }
414	        : null,
415	    [wsyncError],
416	  );
417	
418	  const value = useMemo<BoardContextValue>(
419	    () => ({
420	      workspaceDetail,
421	      features,
422	      trackedFeatures,
423	      loading,
424	      error,
425	      reload: reloadAll,
426	      syncing,
427	      syncError,
428	      syncBoard,
429	
430	      boardMode,
431	      setBoardMode: handleSetBoardMode,
432	
433	      taskSearchQuery,
434	      setTaskSearchQuery,
435	      taskActiveFilters,
436	      setTaskActiveFilters: handleSetTaskActiveFilters,
437	
438	      featureSearchQuery,
439	      setFeatureSearchQuery,
440	      featureActiveFilters,
441	      setFeatureActiveFilters: handleSetFeatureActiveFilters,
442	
443	      // Aliases for existing Task Mode consumers
444	      searchQuery: taskSearchQuery,
445	      setSearchQuery: setTaskSearchQuery,
446	      activeFilters: taskActiveFilters,
447	      setActiveFilters: handleSetTaskActiveFilters,
448	
449	      expandedFeatureIds,
450	      toggleFeature,
451	
452	      backendTaskResults,
453	      backendFeatureResults,
454	      taskSearching,
455	      featureSearching,
456	      taskSearchError,
457	      featureSearchError,
458	      openTaskTab,
459	      openTaskTabNewSession,
460	      openFeatureTab,
461	      openFeatureTabNewSession,
462	
463	      taskPage,
464	      setTaskPage,
465	      featurePage,
466	      setFeaturePage,
467	      taskPagination,
468	      featurePagination,
469	
470	      taskLimit,
471	      setTaskLimit,
472	      featureLimit,
473	      setFeatureLimit,
474	    }),
475	    [
476	      workspaceDetail,
477	      features,
478	      trackedFeatures,
479	      loading,
480	      error,
481	      reloadAll,
482	      syncing,
483	      syncError,
484	      syncBoard,
485	      boardMode,
486	      handleSetBoardMode,
487	      taskSearchQuery,
488	      taskActiveFilters,
489	      handleSetTaskActiveFilters,
490	      featureSearchQuery,
491	      featureActiveFilters,
492	      handleSetFeatureActiveFilters,
493	      expandedFeatureIds,
494	      toggleFeature,
495	      backendTaskResults,
496	      backendFeatureResults,
497	      taskSearching,
498	      featureSearching,
499	      taskSearchError,
500	      featureSearchError,
501	      openTaskTab,
502	      openTaskTabNewSession,
503	      openFeatureTab,
504	      openFeatureTabNewSession,
505	
506	      taskPage,
507	      featurePage,
508	      taskPagination,
509	      featurePagination,
510	
511	      taskLimit,
512	      featureLimit,
513	    ],
514	  );
515	
516	  const trackingValue = useMemo<BoardTrackingContextValue>(
517	    () => ({
518	      trackedFeatures,
519	      openTaskTab,
520	      openTaskTabNewSession,
521	    }),
522	    [trackedFeatures, openTaskTab, openTaskTabNewSession],
523	  );
524	
525	  return (
526	    <BoardContext.Provider value={value}>
527	      <BoardTrackingContext.Provider value={trackingValue}>
528	        {children}
529	      </BoardTrackingContext.Provider>
530	    </BoardContext.Provider>
531	  );
532	}
