534	export function useBoardContext(): BoardContextValue {
535	  const ctx = useContext(BoardContext);
536	  if (!ctx) {
537	    throw new Error("useBoardContext must be used within a BoardProvider");
538	  }
539	  return ctx;
540	}
541	
542	export function useBoardTrackingContext(): BoardTrackingContextValue {
543	  const ctx = useContext(BoardTrackingContext);
