"use client";

import { useActivity } from "../../hooks/useActivity";
import { ActivityFeed } from "../ActivityFeed";
import type { FeatureDetail } from "@/services/workflow-backend/types";

type FeatureLogsPanelProps = {
  feature: FeatureDetail;
  workspaceId: string;
};

export function FeatureLogsPanel({ feature, workspaceId }: FeatureLogsPanelProps) {
  const { events, loading } = useActivity(workspaceId);

  const featureEvents = events.filter(
    (e) =>
      e.feature_id === feature.id ||
      e.feature_id === feature.feature_id ||
      e.feature_id === feature.feature_name,
  );

  const sortedEvents = featureEvents
    .map((entry, sequence) => {
      const t = new Date(entry.occurred_at).getTime();
      return { ...entry, sortTime: Number.isNaN(t) ? Number.NEGATIVE_INFINITY : t, sequence };
    })
    .sort((a, b) => {
      if (a.sortTime !== b.sortTime) return b.sortTime - a.sortTime;
      return a.sequence - b.sequence;
    });

  return (
    <div data-feature-logs-panel className="px-6 py-6">
      <div className="w-1/2 bg-surface">
        <ActivityFeed
          events={sortedEvents}
          loading={loading}
          title="Feature Logs"
        />
      </div>
    </div>
  );
}

